+                <AddTaskForm OnSave="HandleAddTask" OnCancel="() => showAddForm = false" />
+            }
+            else
+            {
+                <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => showAddForm = true">
+                    + Add Task
+                </button>
+            }
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired]
+    public string ColumnName { get; set; } = "";
+
+    [Parameter, EditorRequired]
+    public string Status { get; set; } = "";
+
+    [Parameter, EditorRequired]
+    public List<TaskItem> Tasks { get; set; } = new();
+
+    [Parameter]
+    public bool ShowMoveLeft { get; set; }
+
+    [Parameter]
+    public bool ShowMoveRight { get; set; }
+
+    /// <summary>Status to move to when moving left.</summary>
+    [Parameter]
+    public string? MoveLeftStatus { get; set; }
+
+    /// <summary>Status to move to when moving right.</summary>
+    [Parameter]
+    public string? MoveRightStatus { get; set; }
+
+    [Parameter]
+    public EventCallback<(int TaskId, string NewStatus)> OnTaskMoved { get; set; }
+
+    [Parameter]
+    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnTaskCreated { get; set; }
+
+    private bool showAddForm;
+
+    private async Task HandleMoveLeft(TaskItem task)
+    {
+        if (MoveLeftStatus is not null)
+            await OnTaskMoved.InvokeAsync((task.Id, MoveLeftStatus));
+    }
+
+    private async Task HandleMoveRight(TaskItem task)
+    {
+        if (MoveRightStatus is not null)
+            await OnTaskMoved.InvokeAsync((task.Id, MoveRightStatus));
+    }
+
+    private async Task HandleAddTask(AddTaskForm.AddTaskModel model)
+    {
+        await OnTaskCreated.InvokeAsync((model.Title, model.Assignee, model.Priority, model.DueDate, Status));
+        showAddForm = false;
+    }
+}
